-- "Mia's Morning" was renamed to "Kofi's Morning", but the text says "She ..." throughout. Kofi reads as a male
-- name, so the protagonist becomes "Lucy". Data only, no grants: UPDATEs the English story and its quiz rows
-- (word-boundary match; the slug stays mias-morning so progress and recordings keep their keys).
-- Narration recorded for the edited sentences is regenerated by scripts/story-audio.ts after this lands.

UPDATE public.stories
SET title = regexp_replace(title, '\mKofi\M', 'Lucy', 'g'),
    segments = regexp_replace(segments::text, '\mKofi\M', 'Lucy', 'g')::jsonb
WHERE course = 'en' AND slug = 'mias-morning';

UPDATE public.story_quiz_questions q
SET prompt = regexp_replace(q.prompt, '\mKofi\M', 'Lucy', 'g'),
    choices = regexp_replace(q.choices::text, '\mKofi\M', 'Lucy', 'g')::jsonb
FROM public.stories s
WHERE s.id = q.story_id AND s.course = 'en' AND s.slug = 'mias-morning';
